dtsPropsFor.DukProvider:
children: React.ReactNode;
/** UI language (default 'sv'). */
lang?: 'sv' | 'en';
/** Demo user signed in: 'user-nurse-1' (nurse, default), 'user-pal-1' / 'user-doc-1' (doctor), 'user-sec-1' (secretary), 'user-patient-1' (patient). Drives role-gated UI. */
userId?: 'user-pal-1' | 'user-doc-1' | 'user-nurse-1' | 'user-sec-1' | 'user-patient-1';
/** Initial in-memory route, e.g. '/worklist' (default '/dashboard'). Ignored when DukProvider is rendered inside an existing router. */
initialPath?: string;

dtsPropsFor.AutoWarningsBadge:
/** Policy-rule warnings; renders nothing when empty. Chip colour follows the highest severity; click opens a details dialog. */
warnings: Array<{ ruleId: string; ruleName: string; severity: 'LOW' | 'MEDIUM' | 'HIGH'; triggeredValues: Record<string, number>; expression: string }>;
/** ISO datetime of the last policy calculation. */
lastActivityAt?: string;

dtsPropsFor.CareRoleIcon:
/** Care role; 'PAL' renders the doctor icon, null renders nothing. */
role: 'DOCTOR' | 'NURSE' | 'PHYSIO' | 'PAL' | null | undefined;
fontSize?: 'inherit' | 'small' | 'medium' | 'large';

dtsPropsFor.ConfirmDialog:
open: boolean;
title: string;
message: string;
/** Defaults to the translated 'Confirm'. */
confirmLabel?: string;
onConfirm: () => void;
onCancel: () => void;
/** Default 'error'. */
confirmColor?: 'error' | 'primary' | 'warning';

dtsPropsFor.DeadlineLabel:
/** ISO date of the deadline. */
deadline: string;
/** 'queue' = muted when far off, warning when <=3 days, bold red when overdue. Default 'default'. */
tone?: 'default' | 'queue';

dtsPropsFor.PersonalNumberCopy:
/** Swedish personnummer (YYYYMMDD-XXXX or 12 digits). */
personalNumber?: string | null;
/** 'long' prefixes the translated label, 'none' shows only the copy button. Default 'short'. */
labelFormat?: 'long' | 'short' | 'none';
showCopy?: boolean;
/** Copy digits only instead of YYYYMMDD-XXXX. */
copyAsRaw?: boolean;
/** MUI colour token, default 'text.secondary'. */
color?: string;
onCopy?: (copied: string) => void;
sx?: object;
'aria-label'?: string;

dtsPropsFor.RoleIcon:
role: 'PATIENT' | 'NURSE' | 'DOCTOR' | 'SECRETARY';
/** Default true - wraps the icon in a tooltip with the role label. */
showTooltip?: boolean;
sx?: object;

dtsPropsFor.TabPanel:
children: React.ReactNode;
/** Currently selected tab index. */
value: number;
/** This panel's index; content renders only when value === index. */
index: number;

dtsPropsFor.TriggerChips:
triggers: Array<'NO_RESPONSE' | 'NOT_OPENED' | 'HIGH_PAIN' | 'INFECTION_SUSPECTED' | 'LOW_FUNCTION' | 'LOW_QOL' | 'SEEK_CONTACT' | 'ABNORMAL_ANSWER' | 'LAB_PENDING' | 'XRAY_PENDING'>;
/** Chips shown before collapsing the rest into '+N'. Default 3. */
maxVisible?: number;

dtsPropsFor.SideNav:
drawerWidth: number;
mobileOpen: boolean;
onClose: () => void;
/** true = temporary drawer, false = permanent drawer (md+). */
isMobile: boolean;
